python - <<'PY'
import numpy as np,json
from PIL import Image
im=np.array(Image.open('/app/output/init_ego.png'));d=np.load('/app/output/obs2_depth.npy');K=np.array(json.load(open('/app/output/spec.json'))['cameras']['ego']['intrinsic_cv']);E=np.array(json.load(open('/app/output/spec.json'))['cameras']['ego']['mount']['extrinsic_cv']);R=E[:,:3];t=E[:,3]
for y in range(180,280,5):
 row=[]
 for x in range(330,410,5):
  c=im[y,x];z=d[y,x]
  if z:
   p=np.array([(x-K[0,2])*z/K[0,0],(y-K[1,2])*z/K[1,1],z]);w=R.T@(p-t)
   if c[0]>130 and c[1]>50 and c[2]<130: row.append(f'{x}:{y} c{c} z{w[2]:.3f}')
 print(' | '.join(row[:5]))
PY

