python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(video='none');n=np.array(o.meta['proprio']['now']);q=np.r_[n[:7],n[8:15]]
seed=q.copy();seed[7:]=[1,-1.5,1,-2,-2,.5,0]
ori=[0,.58778525,.80901699,0];res=r.ik({'Gripper_Tip_L':[.353,.006,.95]+ori},seed=seed,tol_pos_m=.01,tol_rot_rad=.08,max_iters=500);goal=res['q'];print('ik',res['ok'],res['error'],np.round(goal[7:],2))
links=['Link3_L','Link4_L','Link5_L','Link6_L','Link7_L','Pika_Gripper_Base_L','Gripper_Tip_L'];tracks={l:[] for l in links}
for u in np.linspace(0,1,31):
 fk=r.fk(q*(1-u)+goal*u,links=links)['poses']
 for l in links: tracks[l].append(fk[l][:3])
for l,pts in tracks.items():
 p=np.array(pts);rad=np.linalg.norm(p[:,:2]-[.353,.006],axis=1);i=rad.argmin();print(l,'closest r',round(rad[i],3),'z',round(p[i,2],3),'point',np.round(p[i],3),'zmin',round(p[:,2].min(),3))
PY

